import math

def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    root = int(math.isqrt(n))
    return root * root == n

def is_cool(n):
    if n == 1:
        # Sum is 1, which is a square.
        return False

    # Backtracking function
    # path: the sequence built so far
    # used: boolean array tracking usage of numbers 1..n
    # current_sum: the sum of numbers in the path
    def backtrack(used, current_sum, length):
        if length == n:
            return True

        for k in range(1, n + 1):
            if not used[k]:
                next_sum = current_sum + k
                if not is_square(next_sum):
                    used[k] = True
                    if backtrack(used, next_sum, length + 1):
                        return True
                    used[k] = False  # Backtrack
        return False

    # used array is 1-indexed
    used = [False] * (n + 1)
    return backtrack(used, 0, 0)

